css:
.fp-ctl{display:flex; flex-wrap:wrap; gap:10px 22px; align-items:center; margin:8px 0}
.fp-ctl input.mi, .kpick input.mi{width:52px}
.fig.wide{max-width:100%; width:100%}
.trow select{font-family:var(--mono); font-size:14px; padding:4px 6px; border:1px solid var(--rule); border-radius:6px; background:var(--panel); color:var(--ink)}
.subh{font-family:var(--display); font-size:15px; margin:18px 0 6px}
.bits{font-family:var(--mono); font-size:13px; word-break:break-all; line-height:1.6; padding:6px 0}
.bits .bs{color:var(--warn)} .bits .be{color:var(--c3)} .bits .bm{color:var(--c1)}
.bits .bl{display:flex; gap:16px; font-size:11.5px; color:var(--muted)}
table.kv.hilb td, table.kv.hilb th{padding-right:22px}
#ct-tab td, #ct-time td{padding-right:22px}
.trow .chips{min-width:0; flex:1 1 220px; flex-wrap:wrap}
.trow{max-width:100%}
#ar-a,#ar-b{width:110px!important}
#ie-status,#fp-status{overflow-wrap:anywhere}
#pw-tab td,#pw-tab th{padding-right:16px}
